"use client";

import { UserProvider } from "@/contexts/UserContext";

export function Providers({ children, serverUser }: { children: React.ReactNode; serverUser?: any }) {
  return (
    <UserProvider initialUser={serverUser}>
      {children}
    </UserProvider>
  );
}

"use client";

import { useEffect, useState, useRef, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import Navbar from "@/components/layout/Navbar";
import Footer from "@/components/layout/Footer";
import Link from "next/link";
import { useUser } from "@/contexts/UserContext";
import LoginModal from "@/components/auth/LoginModal";
import BookingsTab from "@/components/account/BookingsTab";

interface User {
  id?: string;
  _id?: string;
  name?: string;
  email?: string;
  phone?: string;
  mobileNumber?: string;
  gender?: string;
  dob?: string;
  placeOfBirth?: string;
  occupation?: string;
  addresses?: Address[];
}

export interface Address {
  _id?: string;
  id?: string;
  type?: string;
  name?: string;
  phone?: string;
  addressLine1?: string;
  addressLine2?: string;
  address?: string;
  landmark?: string;
  city?: string;
  state?: string;
  pincode?: string;
  country?: string;
  isDefault?: boolean;
}

export interface WishlistItem {
  wishlistId?: string;
  serviceId?: string;
  serviceType?: string;
  slug?: string;
  image?: string;
  name?: string;
  location?: string;
  price?: number | string;
  [key: string]: unknown;
}

const ACCOUNT_TABS = [
  {
    id: "profile",
    label: "Profile",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
      </svg>
    ),
  },
  {
    id: "bookings",
    label: "My Bookings",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 2v3m-5 1l5-3 5 3v2H7V6zm-2 4h14v11H5V10zm5 11v-5a2 2 0 014 0v5" />
      </svg>
    ),
  },
  {
    id: "subscriptions",
    label: "My Subscriptions",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
      </svg>
    ),
  },
  {
    id: "wallet",
    label: "Wallet",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h18M7 15h1m4 0h1m-7 4h12a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
      </svg>
    ),
  },
  {
    id: "wishlist",
    label: "Wishlist",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
      </svg>
    ),
  },
  {
    id: "address",
    label: "Saved Address",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
      </svg>
    ),
  },
  {
    id: "language",
    label: "Language",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 12a9 9 0 01-9 9m9-9a9 9 0 00-9-9m9 9H3m9 9a9 9 0 01-9-9m9 9c1.657 0 3-4.03 3-9s-1.343-9-3-9m0 18c-1.657 0-3-4.03-3-9s1.343-9 3-9m-9 9a9 9 0 019-9" />
      </svg>
    ),
  },
  {
    id: "about",
    label: "About",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    ),
  },
  {
    id: "support",
    label: "Support",
    icon: (active: boolean) => (
      <svg className={`w-4 h-4 shrink-0 ${active ? "" : "text-gray-500"}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18.364 5.636l-3.536 3.536m0 5.656l3.536 3.536M9.172 9.172L5.636 5.636m3.536 9.192l-3.536 3.536M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-5 0a4 4 0 11-8 0 4 4 0 018 0z" />
      </svg>
    ),
  },
];

function AccountPageContent() {
  const searchParams = useSearchParams();
  const { user, setUser } = useUser();
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("profile");

  useEffect(() => {
    const tabParam = searchParams.get('tab');
    if (tabParam) {
      setActiveTab(tabParam);
    }
  }, [searchParams]);

  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [formData, setFormData] = useState<User>({});
  const [saving, setSaving] = useState(false);

  const [wishlistItems, setWishlistItems] = useState<WishlistItem[]>([]);
  const [loadingWishlist, setLoadingWishlist] = useState(false);

  const addresses = user?.addresses || [];
  const [bookingsCount, setBookingsCount] = useState(0);
  const [subscriptionFilter, setSubscriptionFilter] = useState("All");

  useEffect(() => {
    const userId = user?._id || user?.id;
    if (userId) {
      const backendUrl = process.env.NEXT_PUBLIC_API_BASE_URL || process.env.NEXT_PUBLIC_BASE_URL || "https://priestservices.astroved.com";
      fetch(`${backendUrl}/api/orders/user/${userId}`)
        .then(res => res.json())
        .then(data => {
          if (data.success && Array.isArray(data.data)) {
            setBookingsCount(data.data.length);
          }
        })
        .catch(err => console.error("Error fetching bookings count:", err));
    }
  }, [user?._id, user?.id]);
  const [showAddressModal, setShowAddressModal] = useState(false);
  const [addressFormData, setAddressFormData] = useState({
    _id: "",
    type: "Home",
    fullName: "",
    phone: "",
    address: "",
    landmark: "",
    city: "",
    state: "",
    pincode: "",
    country: "India",
    isDefault: false
  });
  const [selectedLanguage, setSelectedLanguage] = useState("English");
  const [openFaq, setOpenFaq] = useState<number | null>(1);

  // Still Need Help States
  const [helpFormData, setHelpFormData] = useState({
    name: "",
    mobileNumber: "",
    email: "",
    bookingId: "",
    subject: "",
    message: "",
    consent: false
  });
  const [isSubmittingHelp, setIsSubmittingHelp] = useState(false);

  const handleHelpSubmit = async () => {
    if (!helpFormData.name || !helpFormData.mobileNumber || !helpFormData.subject || !helpFormData.message || !helpFormData.consent) {
      alert("Please fill all required fields and accept the consent.");
      return;
    }
    setIsSubmittingHelp(true);
    try {
      const baseUrl = process.env.NEXT_PUBLIC_API_BASE_URL || process.env.NEXT_PUBLIC_BASE_URL || "https://priestservices.astroved.com";

      const res = await fetch(`${baseUrl}/api/customerQueries`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...helpFormData,
          userId: user?.id || user?._id || undefined
        }),
      });
      const data = await res.json();
      if (data.success) {
        alert("Your request has been submitted successfully!");
        setHelpFormData({
          name: "",
          mobileNumber: "",
          email: "",
          bookingId: "",
          subject: "",
          message: "",
          consent: false
        });
      } else {
        alert(data.message || "Failed to submit request.");
      }
    } catch (error) {
      alert("Error submitting request.");
    } finally {
      setIsSubmittingHelp(false);
    }
  };

  // Login Modal States
  const [showLoginModal, setShowLoginModal] = useState(false);


  useEffect(() => {
    if (typeof window !== "undefined" && window.location.hash) {
      const hashTab = window.location.hash.replace("#", "");
      if (["profile", "bookings", "subscriptions", "wallet", "wishlist", "address", "language"].includes(hashTab)) {
        setActiveTab(hashTab);
      }
    }
  }, []);

  const fetchWishlist = async () => {
    if (!user || (!user.id && !user._id)) return;
    setLoadingWishlist(true);
    try {
      const baseUrl = process.env.NEXT_PUBLIC_API_BASE_URL || process.env.NEXT_PUBLIC_BASE_URL || "https://priestservices.astroved.com";
      const res = await fetch(`${baseUrl}/api/wishlist/${user.id || user._id}`);
      const data = await res.json();
      if (data.success && data.data) {
        setWishlistItems(data.data);
      }
    } catch (err) {
      console.error("Failed to fetch wishlist", err);
    } finally {
      setLoadingWishlist(false);
    }
  };

  useEffect(() => {
    if (user) {
      fetchWishlist();
    }
  }, [user]);

  const handleLogout = async () => {
    try {
      await fetch(`${process.env.NEXT_PUBLIC_BASE_URL || "https://priestservices.astroved.com"}/api/auth/logout`, { method: "POST" });
    } catch {
      // ignore
    }
    document.cookie = "userLogin=false; path=/; max-age=0;";
    setUser(null);
  };



  const handleSave = async () => {
    setSaving(true);
    try {
      const baseUrl = process.env.NEXT_PUBLIC_API_BASE_URL || process.env.NEXT_PUBLIC_BASE_URL || "https://priestservices.astroved.com";

      const res = await fetch(`${baseUrl}/api/users/updateProfile`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          userId: user?.id,
          name: (formData.name || '').trim(),
          email: (formData.email || '').trim(),
          mobileNumber: (formData.mobileNumber || formData.phone || '').trim(),
        }),
      });

      const data = await res.json();
      if (data.success) {
        const updatedUser = { ...user, ...data.data };
        setUser(updatedUser);
        // Mock update state
        setShowEditModal(false);
      } else {
        alert(data.message || "Failed to update profile");
      }
    } catch (error) {
      alert("Error updating profile");
      console.error('Error updating profile:', error);
    } finally {
      setSaving(false);
    }
  };

  const handleSaveAddress = async () => {
    if (!user) return;
    try {
      const baseUrl = process.env.NEXT_PUBLIC_API_BASE_URL || process.env.NEXT_PUBLIC_BASE_URL || "https://priestservices.astroved.com";

      const newAddress = {
        type: addressFormData.type,
        name: addressFormData.fullName,
        phone: addressFormData.phone,
        addressLine1: addressFormData.address,
        addressLine2: addressFormData.landmark,
        city: addressFormData.city,
        state: addressFormData.state,
        pincode: addressFormData.pincode,
        country: addressFormData.country,
        isDefault: addressFormData.isDefault
      };

      let updatedAddresses = [...(user.addresses || [])];

      if (newAddress.isDefault) {
        updatedAddresses = updatedAddresses.map(a => ({ ...a, isDefault: false }));
      } else if (updatedAddresses.length === 0) {
        newAddress.isDefault = true;
      }

      if (addressFormData._id) {
        const index = updatedAddresses.findIndex(a => a._id === addressFormData._id);
        if (index > -1) {
          updatedAddresses[index] = { ...updatedAddresses[index], ...newAddress };
        }
      } else {
        updatedAddresses.push({ ...newAddress });
      }

      const payload = {
        userId: user.id || user._id,
        name: user.name || "",
        email: user.email || "",
        mobileNumber: user.mobileNumber || "",
        addresses: updatedAddresses
      };

      const res = await fetch(`${baseUrl}/api/users/updateProfile`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });

      const data = await res.json();
      if (data.success) {
        const updatedUser = { ...user, ...data.data };
        setUser(updatedUser);
        // Mock update state
        setShowAddressModal(false);
      } else {
        alert(data.message || "Failed to save address");
      }
    } catch (error) {
      alert("Error saving address");
    }
  };

  const handleDeleteAddress = async (addressId: string) => {
    if (!user) return;
    if (!window.confirm("Are you sure to delete the address?")) return;

    try {
      const baseUrl = process.env.NEXT_PUBLIC_API_BASE_URL || process.env.NEXT_PUBLIC_BASE_URL || "https://priestservices.astroved.com";

      const updatedAddresses = (user.addresses || []).filter((a: Address) => a._id !== addressId && a.id !== addressId);

      if (updatedAddresses.length > 0 && !updatedAddresses.some((a: Address) => a.isDefault)) {
        updatedAddresses[0].isDefault = true;
      }

      const payload = {
        userId: user.id || user._id,
        name: user.name || "",
        email: user.email || "",
        mobileNumber: user.mobileNumber || "",
        addresses: updatedAddresses
      };
      const res = await fetch(`${baseUrl}/api/users/updateProfile`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (data.success) {
        const updatedUser = { ...user, ...data.data };
        setUser(updatedUser);
        // Mock update state
      } else {
        alert(data.message || "Failed to delete address");
      }
    } catch (error) {
      alert("Error deleting address");
    }
  };

  const openEditAddressModal = (addr: Address) => {
    setAddressFormData({
      _id: addr._id || "",
      type: addr.type || "Home",
      fullName: addr.name || "",
      phone: addr.phone || "",
      address: addr.addressLine1 || "",
      landmark: addr.addressLine2 || "",
      city: addr.city || "",
      state: addr.state || "",
      pincode: addr.pincode || "",
      country: addr.country || "India",
      isDefault: addr.isDefault || false
    });
    setShowAddressModal(true);
  };


  const openAddAddressModal = () => {
    setAddressFormData({
      _id: "",
      type: "Home",
      fullName: "",
      phone: "",
      address: "",
      landmark: "",
      city: "",
      state: "",
      pincode: "",
      country: "India",
      isDefault: false
    });
    setShowAddressModal(true);
  };

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#fafafc]">
        <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-success"></div>
      </div>
    );
  }

  return (
    <>
      <Navbar />
      <main className="min-h-screen bg-[#fafafc] pb-16 font-sans">

        {/* ── Breadcrumb Bar ── */}
        <div className="border-b border-gray-150 bg-white">
          <div className="mx-auto max-w-[1350px] px-4 sm:px-6 lg:px-10 py-3.5 flex items-center gap-4">
            <div className="flex items-center gap-2 text-xs font-semibold text-gray-500 overflow-x-auto whitespace-nowrap [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
              <Link href="/" className="hover:text-gray-900 transition">HOME</Link>
              <span className="text-gray-300">›</span>
              <button onClick={() => { setActiveTab('profile'); setIsDrawerOpen(false); }} className={`transition ${activeTab === 'profile' ? 'text-gray-900 font-bold' : 'hover:text-gray-900'}`}>Account</button>
              {activeTab !== 'profile' && (
                <>
                  <span className="text-gray-300">›</span>
                  <span className="text-gray-900 font-bold">
                    {ACCOUNT_TABS.find((t) => t.id === activeTab)?.label || activeTab}
                  </span>
                </>
              )}
            </div>
          </div>
        </div>

        {/* ── Main Container: Sidebar + Content ── */}
        <div className="mx-auto max-w-[1350px] px-2.5 sm:px-6 lg:px-10 pt-4 sm:pt-8 pb-16">
          {!user ? (
            <div className="flex flex-col items-center justify-center pt-24 pb-40 text-center">
              <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mb-4">
                <svg className="w-8 h-8 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                </svg>
              </div>
              <h2 className="text-xl font-bold text-gray-800 mb-2">Authentication Required</h2>
              <p className="text-gray-500 max-w-sm mb-6">You must be logged in to access your account settings and history.</p>
              <button
                onClick={() => setShowLoginModal(true)}
                className="bg-success text-white font-bold py-2.5 px-8 rounded-full hover:bg-[#058a51] transition"
              >
                Login Now
              </button>
            </div>
          ) : (
            <>
              {/* ── Mobile/Tablet Tab Selector Bar (< xl / 1024px) ── */}
              <div className="xl:hidden w-full mb-6">
                <button
                  type="button"
                  onClick={() => setIsDrawerOpen(true)}
                  className="w-full bg-white border border-gray-200 rounded-xl px-4 py-3 sm:py-3.5 flex items-center justify-between shadow-2xs hover:border-gray-300 transition text-left cursor-pointer"
                >
                  <div className="flex items-center gap-3">
                    <svg className="w-5 h-5 text-success shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16M4 18h16" />
                    </svg>
                    <span className="font-bold text-gray-900 text-sm sm:text-base capitalize">
                      {ACCOUNT_TABS.find((t) => t.id === activeTab)?.label || "Profile"}
                    </span>
                  </div>
                  <svg
                    className={`w-4 h-4 text-gray-500 transition-transform duration-200 shrink-0 ${isDrawerOpen ? "rotate-180" : ""}`}
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                  </svg>
                </button>
              </div>

              {/* ── Mobile/Tablet Backdrop Overlay (< xl / 1024px) ── */}
              {isDrawerOpen && (
                <div
                  className="fixed inset-0 z-[90] bg-black/50 backdrop-blur-xs xl:hidden transition-opacity duration-300"
                  onClick={() => setIsDrawerOpen(false)}
                />
              )}

              {/* ── Mobile/Tablet Off-canvas Card Drawer (< xl / 1024px, Matching Reference) ── */}
              <div
                className={`fixed top-0 bottom-0 left-0 z-[100] h-[100dvh] w-[82vw] max-w-[315px] bg-white shadow-2xl p-5 pb-6 sm:pb-8 flex flex-col justify-between overflow-hidden transition-transform duration-300 ease-out xl:hidden ${isDrawerOpen
                    ? "translate-x-0"
                    : "-translate-x-full pointer-events-none"
                  }`}
              >
                {/* Modal Header */}
                <div className="flex items-center justify-between pt-1 pb-3 mb-1 shrink-0">
                  <span className="text-xl font-serif font-bold text-gray-900 tracking-tight">Account</span>
                  <button
                    type="button"
                    onClick={() => setIsDrawerOpen(false)}
                    className="p-1.5 text-gray-700 hover:text-black hover:bg-gray-100 rounded-full transition cursor-pointer"
                    aria-label="Close menu"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>

                {/* Modal Nav Items */}
                <div className="flex-1 flex flex-col gap-1 sm:gap-1.5 overflow-y-auto py-1 overscroll-contain [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
                  {ACCOUNT_TABS.map((tab) => {
                    const isActive = activeTab === tab.id;
                    return (
                      <button
                        key={tab.id}
                        type="button"
                        onClick={() => {
                          setActiveTab(tab.id);
                          setIsDrawerOpen(false);
                        }}
                        className={`w-full flex items-center gap-3.5 px-4 py-2.5 sm:py-3 rounded-2xl text-[14px] sm:text-[15px] transition text-left cursor-pointer ${isActive
                            ? "bg-success text-white font-bold shadow-xs"
                            : "text-gray-900 font-semibold hover:bg-gray-50"
                          }`}
                      >
                        {tab.icon(isActive)}
                        <span>{tab.label}</span>
                      </button>
                    );
                  })}
                </div>

                {/* Modal Logout */}
                <div className="pt-2 mt-auto shrink-0">
                  <button
                    type="button"
                    onClick={() => {
                      setIsDrawerOpen(false);
                      handleLogout();
                    }}
                    className="w-full border-2 border-success text-success hover:bg-green-50 font-bold py-2.5 sm:py-3 px-4 rounded-2xl flex items-center justify-center gap-2 text-[14px] sm:text-[15px] transition cursor-pointer"
                  >
                    <svg className="w-4 h-4 text-success" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                    </svg>
                    <span>Logout</span>
                  </button>
                </div>
              </div>

              <div className="flex flex-col xl:flex-row gap-8 items-start">
                {/* ── Left Sidebar Navigation (Desktop >= xl) ── */}
