"use client";
import React, { useEffect, useState, useCallback, useMemo } from "react";
import Navbar from "@/components/layout/Navbar";
import { SparklesIcon } from "@heroicons/react/24/outline";
import { useRouter } from "next/navigation";
import WishlistButton from "@/components/common/WishlistButton";

interface Puja {
  _id: string;
  title: string;
  subtitle?: string;
  description?: string;
  imageUrl: string;
  badge?: string;
  shortTitle?: string;
  buttonText: string;
  location?: string;
  date?: string;
  slug?: string;
  details?: {
    benefits?: { title: string; description: string }[];
    templeLocation?: string;
  };
  deity?: string;
  tithis?: string;
  dosha?: string;
  benefit?: string;
  filterLocation?: string;
  productId?: number;
}


const slugify = (value: string) =>
  value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");

const getPujaImageUrl = (imageUrl?: string): string => {
  if (!imageUrl || typeof imageUrl !== "string") return "";
  const trimmed = imageUrl.trim();
  if (!trimmed) return "";
  if (trimmed.startsWith("http://") || trimmed.startsWith("https://") || trimmed.startsWith("data:") || trimmed.startsWith("/")) {
    return trimmed;
  }
  return `/${trimmed}`;
};

interface FilterGroup {
  label: string;
  options: { value: string }[];
}

type FilterState = Record<string, string[]>; // label -> array of selected values

const defaultFilters: FilterState = {
  Deity: [],
  Tithis: [],
  Dosha: [],
  Benefits: [],
  Location: [],
};

/** Returns true if the puja matches ALL active filters */
function pujaMatchesFilters(
  puja: Puja,
  filters: FilterState,
  searchQuery: string,
  filterGroups: FilterGroup[]
): boolean {
  if (searchQuery.trim()) {
    const q = searchQuery.toLowerCase();
    const searchMatches = [puja.title, puja.subtitle, puja.description, puja.location, puja.badge]
      .filter(Boolean)
      .some((text) => text?.toLowerCase().includes(q));
    if (!searchMatches) return false;
  }

  const fieldMapping: Record<string, keyof Puja> = {
    Deity: "deity",
    Tithis: "tithis",
    Dosha: "dosha",
    Benefits: "benefit",
    Location: "filterLocation",
  };

  for (const group of filterGroups) {
    const selectedValues = filters[group.label];
    if (!selectedValues || selectedValues.length === 0) continue;

    const groupMatches = selectedValues.some((selectedValue) => {
      const fieldName = fieldMapping[group.label];
      const savedValue = fieldName ? puja[fieldName] : undefined;

      if (typeof savedValue === "string" && savedValue.trim()) {
        if (savedValue.trim().toLowerCase() === selectedValue.toLowerCase()) {
          return true;
        }
      }

      if (group.label === "Location" && puja.location) {
        if (puja.location.toLowerCase().includes(selectedValue.toLowerCase())) {
          return true;
        }
      }

      return false;
    });

    if (!groupMatches) return false;
  }
  return true;
}

function PujaFilterModal({
  filters,
  filterGroups,
  initialTab,
  onClose,
  onApply,
  onClear,
}: {
  filters: FilterState;
  filterGroups: FilterGroup[];
  initialTab?: string;
  onClose: () => void;
  onApply: (filters: FilterState) => void;
  onClear: () => void;
}) {
  const [draftFilters, setDraftFilters] = useState<FilterState>(filters);
  const [activeTab, setActiveTab] = useState<string>(
    (initialTab && filterGroups.some((g) => g.label === initialTab))
      ? initialTab
      : filterGroups[0]?.label || ""
  );
  const [searchQuery, setSearchQuery] = useState("");

  const selectFilter = (label: string, value: string) => {
    setDraftFilters((prev) => {
      const current = prev[label] || [];
      if (current.includes(value)) {
        return { ...prev, [label]: current.filter((v) => v !== value) };
      } else {
        return { ...prev, [label]: [...current, value] };
      }
    });
  };

  const activeGroup = filterGroups.find((g) => g.label === activeTab) || filterGroups[0];
  const filteredOptions = activeGroup
    ? activeGroup.options.filter((o) =>
      o.value.toLowerCase().includes(searchQuery.toLowerCase())
    )
    : [];

  const totalSelectedCount = Object.values(draftFilters).reduce(
    (acc, curr) => acc + (curr?.length || 0),
    0
  );

  if (filterGroups.length === 0) return null;

  return (
    <div className="fixed inset-0 z-[999] flex items-center justify-center bg-black/60 p-2.5 sm:p-4 backdrop-blur-sm transition-opacity duration-300">
      <div className="w-full max-w-[550px] h-[82vh] max-h-[580px] flex flex-col overflow-hidden rounded-[20px] bg-white shadow-2xl animate-[fadeIn_0.2s_ease-out]">

        {/* Header */}
        <div className="flex items-center justify-between px-5 sm:px-6 py-3.5 sm:py-4 border-b border-[#ebd5c1] shrink-0 bg-white">
          <h3 className="text-lg sm:text-[22px] font-serif font-bold text-ink">Puja Filters</h3>
          <button onClick={onClose} aria-label="Close filters" className="p-1 text-gray-400 hover:text-gray-700 transition-colors">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {/* Body */}
        <div className="flex flex-1 min-h-0 overflow-hidden">
          {/* Sidebar */}
          <div className="w-[36%] sm:w-1/3 border-r border-[#ebd5c1] overflow-y-auto bg-stone-50/50">
            {filterGroups.map((group) => {
              const isActive = group.label === activeTab;
              const groupSelectedCount = (draftFilters[group.label] || []).length;
              return (
                <button
                  key={group.label}
                  onClick={() => {
                    setActiveTab(group.label);
                    setSearchQuery("");
                  }}
                  className={`w-full text-left px-3 sm:px-4 py-3 sm:py-3.5 text-xs sm:text-sm font-bold transition-colors relative flex items-center justify-between ${isActive ? 'bg-[#fcf5f3] text-[#009644]' : 'text-gray-700 hover:bg-gray-100/60'}`}
                >
                  <span className="truncate">{group.label}</span>
                  {groupSelectedCount > 0 && (
                    <span className="w-4 h-4 rounded-full bg-[#009644] text-white text-[10px] font-bold flex items-center justify-center shrink-0 ml-1">
                      {groupSelectedCount}
                    </span>
                  )}
                  {isActive && <div className="absolute left-0 top-0 bottom-0 w-1 bg-[#009644]"></div>}
                </button>
              )
            })}
          </div>

          {/* Content */}
          <div className="w-[64%] sm:w-2/3 p-3.5 sm:p-5 overflow-y-auto relative custom-scrollbar bg-white">
            <h4 className="text-sm sm:text-base font-bold text-[#9e1c1c] mb-2.5 sm:mb-4">{activeGroup.label}</h4>

            {/* Search */}
            <div className="relative mb-3.5 sm:mb-5">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder={`Search ${activeGroup.label}`}
                className="w-full pl-8 sm:pl-9 pr-3 py-1.5 sm:py-2 border border-gray-200 rounded-full outline-none text-xs sm:text-sm focus:border-[#009644] transition-colors"
              />
              <svg className="w-3.5 h-3.5 text-gray-400 absolute left-2.5 top-1/2 -translate-y-1/2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-4.35-4.35M17 10a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>

            {/* Options */}
            <div className="space-y-3 sm:space-y-4">
              {filteredOptions.length > 0 ? (
                filteredOptions.map((option) => {
                  const isSelected = (draftFilters[activeGroup.label] || []).includes(option.value);
                  return (
                    <label key={option.value} className="flex items-start gap-2.5 cursor-pointer group select-none">
                      <div className="relative flex items-center justify-center shrink-0 mt-0.5">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => selectFilter(activeGroup.label, option.value)}
                          className="peer w-[18px] h-[18px] appearance-none rounded-[4px] border border-gray-300 checked:bg-white checked:border-[#009644] transition-colors cursor-pointer"
                        />
                        {/* Custom checkmark */}
                        <svg className="absolute w-3 h-3 text-transparent peer-checked:text-[#009644] pointer-events-none transition-colors" viewBox="0 0 14 10" fill="none">
                          <path d="M1 5L4.5 8.5L13 1" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                      </div>
                      <span className="text-xs sm:text-sm font-semibold text-gray-700 group-hover:text-gray-900 leading-snug pt-[1px]">{option.value}</span>
                    </label>
                  )
                })
              ) : (
                <p className="text-xs sm:text-sm text-gray-500 text-center py-4">No matching options found.</p>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="shrink-0 flex items-center justify-between px-3.5 py-3 sm:px-6 sm:py-3.5 border-t border-[#ebd5c1] gap-2.5 sm:gap-3 bg-white shadow-[0_-4px_16px_rgba(0,0,0,0.06)] z-10">
          <button
            type="button"
            onClick={() => { setDraftFilters(defaultFilters); onClear(); }}
            className="flex-1 h-11 sm:h-12 border border-gray-300 hover:border-gray-400 bg-gray-50 hover:bg-gray-100 active:bg-gray-200 rounded-full text-xs sm:text-sm font-bold text-gray-700 transition-all text-center flex items-center justify-center shadow-xs"
          >
            Clear Filter
          </button>
          <button
            type="button"
            onClick={() => onApply(draftFilters)}
            className="flex-1 h-11 sm:h-12 bg-[#009644] hover:bg-[#00803a] active:bg-[#006e32] text-white rounded-full text-xs sm:text-sm font-bold flex items-center justify-center gap-1.5 shadow-md shadow-green-900/20 active:scale-[0.99] transition-all group"
          >
            <span>Apply Filter</span>
            {totalSelectedCount > 0 && (
              <span className="bg-white/25 text-white text-[11px] font-extrabold px-1.5 py-0.5 rounded-full min-w-[18px] text-center">
                {totalSelectedCount}
              </span>
            )}
            <svg className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-white group-hover:translate-x-0.5 transition-transform shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M14 5l7 7m0 0l-7 7m7-7H3" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
}

import ShareModal, { ShareData } from "@/components/common/ShareModal";

// --- Main Page ----------------------------------------------------------------
export default function PujaClient({ initialPujas }: { initialPujas?: Puja[] }) {
  const [allPujas, setAllPujas] = useState<Puja[]>(initialPujas || []);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [fetched, setFetched] = useState(true);
  const [filters, setFilters] = useState<FilterState>(defaultFilters);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [filterModalInitialTab, setFilterModalInitialTab] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [shareModalOpen, setShareModalOpen] = useState(false);
  const [shareData, setShareData] = useState<ShareData>({});
  const router = useRouter();

  const openFilterModal = (tabLabel?: string) => {
    setFilterModalInitialTab(tabLabel || "");
    setIsFilterModalOpen(true);
  };

  const openShareModal = (data: ShareData) => {
    setShareData(data);
    setShareModalOpen(true);
  };

  // Limit carousel to first 5 pujas
  const carouselPujas = allPujas.slice(0, 5);

  // Banner auto-rotate
  useEffect(() => {
    if (carouselPujas.length <= 1) return;
    const id = setInterval(() => {
      setCurrentIndex((prev) => (prev === carouselPujas.length - 1 ? 0 : prev + 1));
    }, 4000);
    return () => clearInterval(id);
  }, [carouselPujas.length]);

  const activeIndex = carouselPujas.length === 0 ? 0 : Math.min(currentIndex, carouselPujas.length - 1);

  const clearFilters = () => setFilters(defaultFilters);
  const applyFilters = useCallback((nextFilters: FilterState) => {
    setFilters(nextFilters);
    setIsFilterModalOpen(false);
  }, []);

  const hasActiveFilters = Object.values(filters).some((arr) => arr && arr.length > 0);

  // Compute dynamic filter groups ONLY from values actually present in saved pujas
  const dynamicFilterGroups = useMemo(() => {
    const extractValues = (key: keyof Puja, altKey?: keyof Puja) => {
      const set = new Set<string>();
      allPujas.forEach((p) => {
        const val1 = p[key];
        if (typeof val1 === "string" && val1.trim()) {
          set.add(val1.trim());
        }
        if (altKey) {
          const val2 = p[altKey];
          if (typeof val2 === "string" && val2.trim()) {
            set.add(val2.trim());
          }
        }
      });
      return Array.from(set).sort();
    };

    const deities = extractValues("deity");
    const tithis = extractValues("tithis");
    const doshas = extractValues("dosha");
    const benefits = extractValues("benefit");
    const locations = extractValues("filterLocation", "location");

    const groups: FilterGroup[] = [];

    if (deities.length > 0) {
      groups.push({
        label: "Deity",
        options: deities.map((v) => ({ value: v })),
      });
    }
    if (tithis.length > 0) {
      groups.push({
        label: "Tithis",
        options: tithis.map((v) => ({ value: v })),
      });
    }
    if (doshas.length > 0) {
      groups.push({
        label: "Dosha",
        options: doshas.map((v) => ({ value: v })),
      });
    }
    if (benefits.length > 0) {
      groups.push({
        label: "Benefits",
        options: benefits.map((v) => ({ value: v })),
      });
    }
    if (locations.length > 0) {
      groups.push({
        label: "Location",
        options: locations.map((v) => ({ value: v })),
      });
    }

    return groups;
  }, [allPujas]);

  // -- Open filter modal if URL has ?filter=... param --
  useEffect(() => {
    if (typeof window !== "undefined") {
      const params = new URLSearchParams(window.location.search);
      const filterParam = params.get("filter");
      if (filterParam) {
        const found = dynamicFilterGroups.find(
          (g) => g.label.toLowerCase() === filterParam.toLowerCase()
        );
        if (found) {
          openFilterModal(found.label);
        } else if (filterParam.toLowerCase() === "location") {
          openFilterModal("Location");
        }
      }
    }
  }, [dynamicFilterGroups]);

  // -- Apply filters to get displayed pujas --
  const displayedPujas = useMemo(() => {
    return allPujas.filter((p) => pujaMatchesFilters(p, filters, searchQuery, dynamicFilterGroups));
  }, [allPujas, filters, searchQuery, dynamicFilterGroups]);

  return (
    <>
      <Navbar />
      <ShareModal
        isOpen={shareModalOpen}
        onClose={() => setShareModalOpen(false)}
        data={shareData}
      />
      <main className="min-h-screen">
        {/* Hero Section - Light Sacred Sandalwood Theme */}
        <div className="bg-gradient-to-b from-[#fff6ef] via-[#fdeee0] to-[#f9e3d0] py-12 md:py-16 text-center border-b border-[#fcd5b5] relative overflow-hidden">
          {/* Left Inverted Mandala Decoration */}
          <div className="absolute left-0 top-0 bottom-0 h-full pointer-events-none opacity-50 z-0 hidden min-[769px]:flex items-center">
            <img
              src="/images/mandala.png"
              alt="Mandala Left"
              className="h-full w-auto object-contain -scale-x-100"
              style={{ transform: "scaleX(-1)" }}
            />
          </div>

          {/* Right Mandala Decoration */}
          <div className="absolute right-0 top-0 bottom-0 h-full pointer-events-none opacity-50 z-0 hidden min-[769px]:flex items-center">
            <img
              src="/images/mandala.png"
              alt="Mandala Right"
              className="h-full w-auto object-contain"
            />
          </div>

          <div className="relative z-10 max-w-[1350px] mx-auto px-4 sm:px-6 lg:px-10">
            <h1 className="text-3xl sm:text-4xl md:text-[48px] font-serif font-extrabold tracking-tight mb-4 leading-tight text-[#2c1209]">
              Book Authentic <span className="text-[#d95a2b]">Divine Pujas</span> Online
            </h1>
            <p className="text-stone-600 text-sm md:text-base max-w-2xl mx-auto mb-8 font-medium leading-relaxed">
              Performed by certified Vedic Pandits in ancient temples across India. Receive live video streaming, personalized sankalpam, and sacred prasadam.
            </p>

            {/* Light Search & Filter Container */}
            <div className="max-w-2xl mx-auto bg-white/90 backdrop-blur-md rounded-2xl p-2.5 sm:p-3 shadow-xl shadow-orange-950/5 border border-[#fcd5b5] flex items-center gap-2">
              <div className="relative flex-1">
                <input
                  type="text"
                  placeholder="What puja are you looking for?"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-5 pr-10 py-3 rounded-xl text-sm text-stone-800 outline-none placeholder:text-stone-400 font-medium bg-transparent"
                />
                <svg className="w-5 h-5 absolute right-3.5 top-1/2 -translate-y-1/2 text-[#d95a2b]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.2" d="M21 21l-4.35-4.35M17 10a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              {dynamicFilterGroups.length > 0 && (
                <button
                  onClick={() => openFilterModal()}
                  className="bg-[#d95a2b] hover:bg-[#c24a1e] text-white px-6 py-3 rounded-xl flex items-center gap-2 text-xs sm:text-sm font-bold shadow-md transition-all shrink-0 active:scale-95 cursor-pointer"
                >
                  <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
                  </svg>
                  <span>Filter</span>
                  {hasActiveFilters && (
                    <span className="w-2 h-2 bg-white rounded-full animate-pulse"></span>
                  )}
                </button>
              )}
            </div>
          </div>
        </div>

        <div className="mx-auto max-w-[1350px] px-4 sm:px-6 lg:px-10 py-10 bg-[#ffffff]">
          <div className="flex items-center justify-between mb-5 sm:mb-6 gap-2">
            <h2 className="text-[19px] min-[360px]:text-[22px] min-[390px]:text-2xl sm:text-3xl lg:text-4xl font-serif font-bold text-[#5c2424] whitespace-nowrap tracking-tight sm:tracking-normal">
              Upcoming Online Pujas
            </h2>
            {hasActiveFilters && (
              <button
                type="button"
                onClick={clearFilters}
                className="text-xs sm:text-sm font-semibold text-red-500 hover:text-red-700 underline shrink-0 whitespace-nowrap"
              >
                Clear Filters
              </button>
            )}
          </div>

          {/* Quick Categories Filter row */}
          {dynamicFilterGroups.length > 0 && (
            <div className="flex overflow-x-auto gap-2.5 pb-4 no-scrollbar mb-6">
              <button
                onClick={clearFilters}
                className={`shrink-0 rounded-full px-5 py-2 text-sm font-bold transition-colors ${!hasActiveFilters ? "bg-[#d95a2b] text-white" : "bg-white text-gray-700 border border-gray-200 hover:bg-gray-50"}`}
              >
                All
              </button>
              {dynamicFilterGroups.map((group: FilterGroup) => (
                <button
                  key={group.label}
                  onClick={() => openFilterModal(group.label)}
                  className={`shrink-0 rounded-full px-5 py-2 text-sm font-bold transition-colors border ${filters[group.label]?.length > 0 ? "bg-[#d95a2b] text-white border-[#d95a2b]" : "bg-white text-gray-700 border-gray-200 hover:bg-gray-50"}`}
                >
                  {group.label}
                </button>
              ))}
            </div>
          )}

          {/* Filter Modal */}
          {isFilterModalOpen && dynamicFilterGroups.length > 0 && (
            <PujaFilterModal
              filters={filters}
              filterGroups={dynamicFilterGroups}
              initialTab={filterModalInitialTab}
              onClose={() => setIsFilterModalOpen(false)}
              onApply={applyFilters}
              onClear={clearFilters}
            />
          )}

          {/* Grid of Cards */}
          {!fetched ? (
            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:gap-8 lg:grid-cols-3 w-full mt-12">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={`skeleton-${i}`} className="bg-gray-100/80 rounded-[32px] h-[450px] animate-pulse border border-stone-100"></div>
              ))}
            </div>
          ) : displayedPujas.length === 0 ? (
            <div className="mt-16 flex flex-col items-center justify-center gap-4 rounded-2xl border border-dashed border-[#e3d1c2] bg-white py-16 text-center">
              <SparklesIcon className="h-10 w-10 text-[#d95a2b]" />
              <p className="text-lg font-semibold text-[#5c2424]">No pujas found</p>
              <p className="text-sm text-gray-500">Try adjusting your filters to find what you're looking for.</p>
              <button
                type="button"
                onClick={clearFilters}
                className="mt-2 rounded-full bg-[#d95a2b] px-6 py-2.5 text-sm font-bold text-white shadow-md hover:bg-[#b0451f] transition"
              >
                Clear Filters
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:gap-8 lg:grid-cols-3">
              {displayedPujas.map((puja: Puja) => {
                const fullUrl = typeof window !== 'undefined' ? `${window.location.origin}/puja/${puja.slug || slugify(puja.title)}` : '';
                return (
                  <div
                    key={puja._id}
                    onClick={() => router.push(`/puja/${puja.slug || slugify(puja.title)}`)}
                    className="bg-white rounded-2xl shadow-md border border-gray-200 flex flex-col overflow-hidden group hover:shadow-2xl hover:shadow-stone-900/15 hover:-translate-y-1.5 transition-all duration-300 relative cursor-pointer"
                  >
                    <div className="flex flex-col flex-1 block">
                      <div className="relative h-[260px] sm:h-[275px] w-full shrink-0 overflow-hidden">
                        <img
                          src={getPujaImageUrl(puja.imageUrl)}
                          alt={puja.title}
                          className="w-full h-full object-fit transition-transform duration-700"
                        />
                        {puja.badge && (
                          <div className="absolute top-4 left-0 bg-[#d92b2b] text-white text-[12px] font-extrabold px-3.5 py-1.5 shadow-md rounded-r-lg uppercase tracking-wider">
                            {puja.badge}
                          </div>
                        )}
                      </div>

                      <div className="p-6 flex flex-col flex-1 text-left">
                        <div className="flex items-center gap-2 mb-2">
                          <div className="w-8 h-[1px] bg-accent/40" />
                          <span className="text-accent font-serif font-extrabold text-xs sm:text-[13px] tracking-wider uppercase flex items-center gap-1.5">
                            <span className="text-[10px]">♦</span> {puja.subtitle} <span className="text-[10px]">♦</span>
                          </span>
                          <div className="w-8 h-[1px] bg-accent/40" />
                        </div>


                        <h3 className="text-[20px] sm:text-[21px] font-serif font-extrabold text-gray-900 mb-2 leading-snug line-clamp-2">
                          {puja.title}
                        </h3>

                        <p className="text-gray-600 text-[14px] leading-relaxed line-clamp-2 mb-5 flex-1">
                          {puja.description}
                        </p>

                        <div className="border border-gray-150 rounded-xl p-3.5 space-y-2.5 mb-5 bg-gray-50/70">
                          <div className="flex items-center gap-2.5 text-[13px] font-medium text-gray-700">
                            <svg className="w-5 h-5 text-[#d95a2b] shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                            <span className="line-clamp-1">{puja.location}</span>
                          </div>
                          <div className="flex items-center gap-2.5 text-[13px] font-medium text-gray-700">
                            <svg className="w-5 h-5 text-[#d95a2b] shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                            <span className="line-clamp-1">{puja.date}</span>
                          </div>
                        </div>

                        <div className="flex items-center justify-between mt-auto pt-2 border-t border-gray-100">
                          <div>
                            {/* Price display */}
                            <div className="text-[20px] sm:text-[22px] font-black text-gray-900">₹{(puja as any).packages?.[0]?.priceINR || (puja as any).packages?.[0]?.price || '516'}</div>
                            <div className="text-[11px] text-gray-500 font-bold uppercase tracking-wider">Per Booking</div>
                          </div>
                          <div
                            className="bg-[#009e5b] text-white text-[14px] font-bold px-7 py-3 min-w-[130px] justify-center rounded-full hover:bg-[#008c51] transition-all duration-200 flex items-center gap-2 shadow-md hover:shadow-lg hover:scale-[1.02] active:scale-95"
                          >
                            <span>Book Now</span>
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7" /></svg>
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* Floating Actions Overlay */}
                    <div className="absolute top-4 right-4 flex flex-col gap-2 z-10" onClick={(e) => e.stopPropagation()}>
                      <WishlistButton itemId={puja._id} />
                      <button
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          openShareModal({
                            title: puja.title,
                            description: puja.subtitle || puja.description,
                            location: puja.location || puja.filterLocation || puja.details?.templeLocation,
                            url: fullUrl,
                          });
                        }}
                        className="w-8 h-8 bg-white rounded-full flex items-center justify-center shadow-sm text-gray-600 hover:text-[#d95a2b] transition-colors"
                      >
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                      </button>
                    </div>
                  </div>
                )
              })}
            </div>
          )}
          {displayedPujas.length > 0 && fetched && (
            <div className="mt-12 text-center pb-10">
              <p className="text-[16px] sm:text-[18px] mb-2 font-medium text-gray-600">You've reached the end of available pujas</p>
              <p className="text-[14px] text-gray-500">{displayedPujas.length} of {displayedPujas.length} pujas shown</p>
            </div>
          )}
        </div>
      </main>
    </>
  );
}

"use client";

import React, { useEffect, useState, useMemo, useRef } from "react";
import { useParams } from "next/navigation";
import Link from "next/link";
import Navbar from "@/components/layout/Navbar";
import Footer from "@/components/layout/Footer";
import LoginModal from "@/components/auth/LoginModal";
import { checkAuthStatus } from "@/lib/authCheck";
import { XMarkIcon } from "@heroicons/react/24/solid";
import WishlistButton from "@/components/common/WishlistButton";
import PujaCountdownCard from "@/components/common/PujaCountdownCard";
import ShareModal from "@/components/common/ShareModal";

interface PujaPackage {
  id: string;
  name: string;
  priceINR?: number;
  priceUSD?: number;
  priceMYR?: number;
  price?: number;
  description?: string;
  imageUrl?: string;
}

interface PujaOffering {
  id: string;
  name: string;
  priceINR?: number;
  priceUSD?: number;
  priceMYR?: number;
  price?: number;
  description?: string;
  badge?: string;
  imageUrl?: string;
  productId?: number;
}

interface Puja {
  _id: string;
  title: string;
  subtitle?: string;
  description?: string;
  imageUrl: string;
  additionalImages?: string[];
  badge?: string;
  shortTitle?: string;
  location?: string;
  templeVenue?: string;
  templeNote?: string;
  templeLocation?: string;
  heroTitle?: string;
  heroSubtitle?: string;
  about?: string;
  strengthFor?: string;
  ritualSummary?: string;
  date?: string;
  eventDateTime?: string;
  slug: string;
  price?: number;
  productId?: number;
  benefits?: { title: string; description: string; icon?: string }[];
  process?: { title: string; description: string }[];
  inclusions?: (string | { title: string; description?: string })[];
  faq?: { question: string; answer: string }[];
  packages?: PujaPackage[];
  offerings?: PujaOffering[];
  gallery?: string[];
  templeImage?: string;
  details?: {
    heroTitle?: string;
    heroSubtitle?: string;
    about?: string;
    templeName?: string;
    templeLocation?: string;
    templeNote?: string;
    templeImage?: string;
    benefits?: { title: string; description: string; icon?: string }[];
    process?: { title: string; description: string }[];
    inclusions?: string[];
    faq?: { question: string; answer: string }[];
  };
}

const slugify = (value: string) =>
  value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");

const getPujaImageUrl = (imageUrl?: string): string => {
  if (!imageUrl || typeof imageUrl !== "string") return "";
  const trimmed = imageUrl.trim();
  if (!trimmed) return "";
  if (trimmed.startsWith("http://") || trimmed.startsWith("https://") || trimmed.startsWith("data:") || trimmed.startsWith("/")) {
    return trimmed;
  }
  return `/${trimmed}`;
};

export default function PujaDetailClient({
  initialPuja,
  recommendations = [],
}: {
  initialPuja: Puja | null;
  recommendations?: any[];
}) {
  const params = useParams<{ slug: string }>();
  const slugParam = params?.slug;
  const slug = Array.isArray(slugParam) ? slugParam[0] : slugParam;
  const currency = "INR";

  const [puja, setPuja] = useState<Puja | null>(initialPuja);
  const [loading, setLoading] = useState(!initialPuja);
  const [selectedPackageId, setSelectedPackageId] = useState<string | null>(null);
  const [showPackageModal, setShowPackageModal] = useState(false);
  const [openFaqIndex, setOpenFaqIndex] = useState<number | null>(0);
  const [activeTab, setActiveTab] = useState("about");
  const [userDetails, setUserDetails] = useState({ name: "", whatsapp: "" });
  const [addingToCart, setAddingToCart] = useState(false);
  const [cartError, setCartError] = useState("");
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [pendingSankalpUrl, setPendingSankalpUrl] = useState<string | null>(null);
  const [isWishlisted, setIsWishlisted] = useState(false);
  const [shareSuccess, setShareSuccess] = useState(false);
  const [shareModalOpen, setShareModalOpen] = useState(false);
  const [showStickyBar, setShowStickyBar] = useState(false);
  const [activeBannerIndex, setActiveBannerIndex] = useState(0);
  const heroCtaRef = useRef<HTMLButtonElement | null>(null);
  const tabsContainerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (tabsContainerRef.current) {
      const activeEl = tabsContainerRef.current.querySelector(`[href="#${activeTab}"]`) as HTMLElement;
      if (activeEl) {
        const container = tabsContainerRef.current;
        const left = activeEl.offsetLeft - container.offsetWidth / 2 + activeEl.offsetWidth / 2;
        container.scrollTo({ left, behavior: "smooth" });
      }
    }
  }, [activeTab]);

  // Scroll handler to show bottom sticky bar only after user scrolls past "About puja" / hero CTA
  useEffect(() => {
    const handleScroll = () => {
      const aboutSec = document.getElementById("about");
      const heroCta = heroCtaRef.current;

      if (aboutSec) {
        const aboutRect = aboutSec.getBoundingClientRect();
        // Show after scrolling down to or past the About Puja section
        setShowStickyBar(aboutRect.top <= 300);
      } else if (heroCta) {
        const ctaRect = heroCta.getBoundingClientRect();
        // Show after hero Book Now button has completely scrolled above the screen
        setShowStickyBar(ctaRect.bottom <= 0);
      } else {
        setShowStickyBar(window.scrollY > 450);
      }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, [loading]);

  // Fetch Puja details by slug
  useEffect(() => {
    if (initialPuja) {
      setPuja(initialPuja);
      setLoading(false);
      return;
    }

    const loadPuja = async () => {
      try {
        if (!slug) {
          setPuja(null);
          return;
        }

        const backendUrl = process.env.NEXT_PUBLIC_API_BASE_URL || process.env.NEXT_PUBLIC_BASE_URL || "https://priestservices.astroved.com";
        const res = await fetch(`${backendUrl}/api/pujas`);
        if (!res.ok) {
          setPuja(null);
          return;
        }

        const resData = await res.json();
        const list: Puja[] = resData?.data && Array.isArray(resData.data)
          ? resData.data
          : Array.isArray(resData)
            ? resData
            : [];

        const match = list.find(
          (p: Puja) => p.slug === slug || slugify(p.title) === slug || p._id === slug
        );

        if (match) {
          setPuja(match);
        } else {
          setPuja(null);
        }
      } catch {
        setPuja(null);
      } finally {
        setLoading(false);
      }
    };

    loadPuja();
  }, [slug, initialPuja]);

  // Handle Tab Scroll Listener
  useEffect(() => {
    const handleScroll = () => {
      const sections = ["about", "benefits", "process", "temple", "receive", "faqs", "gallery"];
      const scrollPosition = window.scrollY + 220;

      for (let i = sections.length - 1; i >= 0; i--) {
        const el = document.getElementById(sections[i]);
        if (el && el.offsetTop <= scrollPosition) {
          setActiveTab(sections[i]);
          break;
        }
      }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const defaultPackageAvatars = [
    "/images/package_individual.webp",
    "/images/partner.webp",
    "/images/package_family.png",
  ];

  // Compute normalized package list from Admin data or defaults
  const packagesList = useMemo(() => {
    const normalizePackageName = (rawName: string, idx: number) => {
      const lower = (rawName || "").toLowerCase();
      if (lower.includes("individual")) return "Individual";
      if (lower.includes("couple")) return "Couple";
      if (lower.includes("family")) return "Family";
      if (idx === 0) return "Individual";
      if (idx === 1) return "Couple";
      if (idx === 2) return "Family";
      return rawName || `Package ${idx + 1}`;
    };

    if (puja?.packages && puja.packages.length > 0) {
      return puja.packages.map((pkg: any, idx: number) => {
        const basePrice = pkg.priceINR ?? pkg.price ?? puja.price ?? 501;
        const defaultDevotees = idx === 0 ? "1 Devotee" : idx === 1 ? "2 Devotees" : idx === 2 ? "4 Devotees" : "Multiple Devotees";
        return {
          id: pkg.id || pkg._id || `pkg-${idx + 1}`,
          name: normalizePackageName(pkg.name, idx),
          devoteeCount: pkg.devoteeCount || pkg.devotees || defaultDevotees,
          priceINR: basePrice,
          priceUSD: pkg.priceUSD,
          priceMYR: pkg.priceMYR,
          description: pkg.description || "Includes personalized sankalpam and video proof.",
          imageUrl: defaultPackageAvatars[idx % defaultPackageAvatars.length],
        };
      });
    }

    const basePrice = puja?.price || 501;
    return [
      {
        id: "pkg-1",
        name: "Individual",
        devoteeCount: "1 Devotee",
        priceINR: basePrice,
        description: "Personalized Sankalpam for 1 Person with video recording.",
        imageUrl: defaultPackageAvatars[0],
      },
      {
        id: "pkg-2",
        name: "Couple",
        devoteeCount: "2 Devotees",
        priceINR: basePrice + 200,
        description: "Personalized Sankalpam for Couple / 2 Devotees.",
        imageUrl: defaultPackageAvatars[1],
      },
      {
        id: "pkg-3",
        name: "Family",
        devoteeCount: "4 Devotees",
        priceINR: basePrice + 400,
        description: "Personalized Sankalpam for 4 Family Members.",
        imageUrl: defaultPackageAvatars[2],
      },
    ];
  }, [puja]);

  // Auto-select first package if none selected
  useEffect(() => {
    if (packagesList.length > 0 && !selectedPackageId) {
      setSelectedPackageId(packagesList[0].id);
    }
  }, [packagesList, selectedPackageId]);

  const getDisplayPrice = (item: any) => {
    return item?.[`price${currency}`] ?? item?.priceINR ?? item?.price ?? 516;
  };

  const selectedPackage = useMemo(() => {
    return (
      packagesList.find((pkg) => pkg.id === selectedPackageId) ??
      packagesList[0] ??
      null
    );
  }, [packagesList, selectedPackageId]);

  const priceVal = selectedPackage
    ? getDisplayPrice(selectedPackage)
    : puja?.price || 516;

  const handleAddPujaToCart = async () => {
    setAddingToCart(true);
    setCartError("");
    try {
      const { is_user } = await checkAuthStatus();
      const actualPujaId = puja?._id || (puja as any)?.id || slug;
      const totalAmount = priceVal;

      const sankalpUrl = `/sankalp?pujaId=${encodeURIComponent(actualPujaId)}&amount=${totalAmount}&type=puja&pkg=${selectedPackageId || ""}&name=${encodeURIComponent(
        userDetails.name
      )}&wa=${userDetails.whatsapp}&title=${encodeURIComponent(puja?.title || "")}&slug=${encodeURIComponent(
        slug || ""
      )}`;

      if (!is_user) {
        setPendingSankalpUrl(sankalpUrl);
        setShowLoginModal(true);
        return;
      }
      window.location.href = sankalpUrl;
    } catch (err: any) {
      setCartError(err.message || "An error occurred. Please try again.");
    } finally {
      setAddingToCart(false);
    }
  };

  if (loading) {
    return (
      <>
        <Navbar />
        <div className="min-h-[60vh] flex items-center justify-center text-[#1f1f1f] font-serif font-bold text-lg">
          Loading sacred puja details...
        </div>
        <Footer />
      </>
    );
  }

  if (!puja) {
    return (
      <>
        <Navbar />
        <div className="min-h-[60vh] flex flex-col items-center justify-center text-center px-4">
          <h1 className="text-3xl font-serif font-bold text-[#221f20] mb-4">Puja Not Found</h1>
          <p className="text-stone-600 mb-6">The requested puja offering could not be found.</p>
          <Link
            href="/puja"
            className="bg-[#00b050] text-white font-extrabold px-8 py-3 rounded-full hover:bg-[#009b46] transition-colors"
          >
            Explore All Pujas
          </Link>
        </div>
        <Footer />
      </>
    );
  }

  // Fallback structures if admin data is not provided
  const defaultBenefits = [
    { title: "Divine Grace & Protection", description: "Invocational blessing to grant strength, peace, and protection.", icon: "🛡️" },
    { title: "Success & Obstacle Removal", description: "Divine support for overcoming difficulties and achieving success.", icon: "🎯" },
    { title: "Prosperity & Abundance", description: "Auspicious sacred rituals bringing prosperity and family wellbeing.", icon: "✨" },
    { title: "Positive Energy & Peace", description: "Strengthen focus, harmony, and positive vibrations at home.", icon: "⚡" },
    { title: "Family Wellbeing", description: "Harmony, happiness, and health for all family members.", icon: "🏡" },
  ];

  const defaultProcess = [
    { title: "Sankalpam", description: "Offering devotee's names and gotram during the sacred ritual by learned priests." },
    { title: "Ganapati Puja & Invocation", description: "Invoking Lord Ganesha for obstruction-free Puja and divine harmony." },
    { title: "Sacred Archana & Chanting", description: "Chanting sacred vedic mantras and 108 names for fulfillment of noble desires." },
    { title: "Mangalarathi & Prasad", description: "Offering final mangalarathi and receiving divine prasad blessings." },
  ];

  const defaultFaqs = [
    { question: "Where is this puja being performed?", answer: "This puja is performed at sacred temples by verified, experienced Vedic pandits following authentic rites." },
    { question: "Why is this puja performed?", answer: "It is performed to seek divine blessings, remove difficulties, and fulfill specific prayers for health, career, and family." },
    { question: "Who will perform the puja?", answer: "Highly experienced Vedic priests with proper initiations will conduct your sankalpam and rituals." },
    { question: "Do I need to be physically present?", answer: "No, physical presence is not required. The pandit recites your Name and Gotra in the Sankalpam, and a full video recording is sent to your WhatsApp within 48 hours." },
  ];

  // Resolve Admin fields with fallbacks
  const aboutText =
    puja.about ||
    puja.details?.about ||
    puja.description ||
    puja.subtitle ||
    puja.heroSubtitle ||
    puja.details?.heroSubtitle ||
    `Perform sacred ${puja.title} with authentic Vedic rituals to seek divine grace, peace, and fulfillment of prayers.`;

  const badgeText =
    puja.badge ||
    puja.shortTitle ||
    puja.subtitle ||
    puja.heroTitle ||
    puja.details?.heroTitle ||
    "SPECIAL SANKALPAM";

  const descriptionText =
    puja.description ||
    puja.subtitle ||
    puja.heroSubtitle ||
    puja.details?.heroSubtitle ||
    "A special sacred ritual for devotees seeking courage, prosperity, and fulfillment of noble wishes.";

  const templeLocationText =
    puja.templeLocation ||
    puja.location ||
    puja.templeVenue ||
    puja.details?.templeLocation ||
    puja.details?.templeName ||
    "Sacred Temple Venue, India";

  const templeVenueText =
    puja.templeVenue ||
    puja.details?.templeName ||
    puja.location ||
    puja.templeLocation ||
    "Sacred Temple Venue";

  const templeNoteText =
    puja.templeNote ||
    puja.details?.templeNote ||
    "This sacred temple is renowned for authentic Vedic rituals, powerful divine vibrations, and traditional archana services.";

  const benefitsList =
    puja.benefits && puja.benefits.length > 0
      ? puja.benefits
      : puja.details?.benefits && puja.details.benefits.length > 0
        ? puja.details.benefits
        : defaultBenefits;

  const processList =
    puja.process && puja.process.length > 0
      ? puja.process
      : puja.details?.process && puja.details.process.length > 0
        ? puja.details.process
        : defaultProcess;

  const faqList =
    puja.faq && puja.faq.length > 0
      ? puja.faq
      : puja.details?.faq && puja.details.faq.length > 0
        ? puja.details.faq
        : defaultFaqs;

  const inclusionsList =
    puja.inclusions && puja.inclusions.length > 0
      ? puja.inclusions
      : puja.details?.inclusions && puja.details.inclusions.length > 0
        ? puja.details.inclusions
        : [
          { title: "Special Invocational Sankalpam", description: "Performed with your name, gotra, and specific prayer request by learned priests." },
          { title: "Full Puja Video Recording", description: "Delivered directly to your WhatsApp number within 48 hours of ritual completion." },
        ];

  const galleryList =
    Array.isArray(puja.gallery) && puja.gallery.length > 0
      ? puja.gallery.map((img: string) => getPujaImageUrl(img)).filter(Boolean)
      : Array.isArray((puja as any).galleryUrl) && (puja as any).galleryUrl.length > 0
        ? (puja as any).galleryUrl.map((img: string) => getPujaImageUrl(img)).filter(Boolean)
        : typeof (puja as any).galleryUrl === "string" && (puja as any).galleryUrl.trim()
          ? [getPujaImageUrl((puja as any).galleryUrl)]
          : [];

  const templeImage =
    (typeof (puja as any).templeImageUrl === "string" && (puja as any).templeImageUrl.trim()) ||
    (typeof puja.templeImage === "string" && puja.templeImage.trim()) ||
    (typeof (puja as any).details?.templeImageUrl === "string" && (puja as any).details.templeImageUrl.trim()) ||
    (typeof puja.details?.templeImage === "string" && puja.details.templeImage.trim()) ||
    "";

  const DEFAULT_BANNER_IMAGE =
    "https://images.unsplash.com/photo-1542909168-82c3e7fdca5c?auto=format&fit=crop&w=1600&q=80";

  const bannerImages: string[] = useMemo(() => {
    if (!puja) return [DEFAULT_BANNER_IMAGE];
    const list: string[] = [];

    const addUrl = (val: any) => {
      if (!val) return;
      if (typeof val === "string") {
        const parts = val.split(/[\n,]+/);
        for (const p of parts) {
          const trimmed = p.trim();
          if (trimmed) {
            const formatted = getPujaImageUrl(trimmed);
            if (formatted) {
              list.push(formatted);
            }
          }
        }
      } else if (Array.isArray(val)) {
        for (const item of val) {
          addUrl(item);
        }
      }
    };

    // 1. Primary main image
    if (puja.imageUrl && typeof puja.imageUrl === "string" && puja.imageUrl.trim()) {
      addUrl(puja.imageUrl);
    }

    // 2. Additional carousel images
    const addImgs = puja.additionalImages || (puja as any).additionalImageUrls;
    const hasAdditional =
      (Array.isArray(addImgs) && addImgs.length > 0) ||
      (typeof addImgs === "string" && Boolean((addImgs as string).trim()));

    if (hasAdditional) {
      addUrl(addImgs);
    } else {
      // 3. Fallback to gallery images if no additionalImages provided
      addUrl(puja.gallery);
      addUrl((puja as any).galleryUrl);
      addUrl((puja as any).details?.gallery);
    }

    // 4. Details sub-object main image
    if (list.length === 0) {
      addUrl((puja?.details as any)?.imageUrl);
    }

    // Fallback default image if no image exists in DB at all
    if (list.length === 0) {
      list.push(DEFAULT_BANNER_IMAGE);
    }

    return list;
  }, [puja]);

  const handlePrevBanner = () => {
    if (bannerImages.length <= 1) return;
    setActiveBannerIndex((prev) => (prev - 1 + bannerImages.length) % bannerImages.length);
  };

  const handleNextBanner = () => {
    if (bannerImages.length <= 1) return;
    setActiveBannerIndex((prev) => (prev + 1) % bannerImages.length);
  };

  const subNavTabs = useMemo(() => [
    { id: "about", label: "About puja" },
    { id: "benefits", label: "Puja Benefits" },
    { id: "process", label: "Puja Procedure" },
    { id: "temple", label: "Temple Details" },
    { id: "receive", label: "What will you receive" },
    { id: "faqs", label: "FAQs" },
    ...(galleryList.length > 0 ? [{ id: "gallery", label: "Puja Gallery" }] : []),
  ], [galleryList.length]);

  return (
    <main className="min-h-screen bg-white text-[#1f1f1f] font-sans">
      <Navbar />

      {/* ── 1. Top Hero Section ── */}
      <section className="bg-[#ffffff] border-b border-[#f0e4d0] py-8 sm:py-12">
        <div className="max-w-[1350px] mx-auto px-4 sm:px-6 lg:px-10">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

            {/* Left 6 Cols: Main Banner Image (Slightly Increased Width) */}
            <div className="lg:col-span-6 flex flex-col">
              <div className="relative w-full h-[280px] sm:h-[350px] md:h-[390px] lg:h-[410px] rounded-xl overflow-hidden border border-stone-200/90 shadow-md group">
                <img
                  src={bannerImages[activeBannerIndex] || (puja ? getPujaImageUrl(puja.imageUrl) : "")}
                  alt={`${puja?.title || "Puja"} - Sacred Ritual Banner ${activeBannerIndex + 1}`}
                  className="w-full h-full object-fit object-center transition-all duration-300"
                />

                {/* Left and Right Navigation Buttons (shown when more than 1 image) */}
                {bannerImages.length > 1 && (
                  <>
                    <button
                      type="button"
                      onClick={handlePrevBanner}
                      aria-label="Previous image"
                      className="absolute left-3 top-1/2 -translate-y-1/2 w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-black/40 hover:bg-black/70 text-white flex items-center justify-center backdrop-blur-sm transition-all shadow-md active:scale-95 z-10"
                    >
                      <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" />
                      </svg>
                    </button>
                    <button
                      type="button"
                      onClick={handleNextBanner}
                      aria-label="Next image"
                      className="absolute right-3 top-1/2 -translate-y-1/2 w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-black/40 hover:bg-black/70 text-white flex items-center justify-center backdrop-blur-sm transition-all shadow-md active:scale-95 z-10"
                    >
                      <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
                      </svg>
                    </button>
                  </>
                )}
              </div>

              {/* Carousel Dots (Shown ONLY when > 1 image, rendering exact length of bannerImages) */}
              {bannerImages.length > 1 && (
                <div className="flex items-center justify-center gap-2 mt-3 mb-1">
                  {bannerImages.map((_, idx) => (
                    <button
                      key={idx}
                      type="button"
                      onClick={() => setActiveBannerIndex(idx)}
                      aria-label={`Go to slide ${idx + 1}`}
                      className={
                        idx === activeBannerIndex
                          ? "w-7 h-2 bg-[#00b050] rounded-full transition-all cursor-pointer"
                          : "w-2.5 h-2.5 bg-stone-300 hover:bg-stone-400 rounded-full transition-all cursor-pointer"
                      }
                    />
                  ))}
                </div>
              )}

              {/* Desktop Only (>=1024px): Frameless Ratings / Stat & Action Strip Under Image */}
              <div className="hidden lg:flex flex-row items-center justify-between gap-2.5 sm:gap-3 mt-3 w-full">
                {/* Stats Container */}
                <div className="flex items-center justify-between flex-1 py-0 px-0">
                  {/* Stat 1: Ratings */}
                  <div className="text-center flex-1 px-1">
                    <span className="block text-sm sm:text-base lg:text-lg font-extrabold text-[#1f1a17] leading-tight">4.36L+</span>
                    <span className="text-[10px] sm:text-xs text-stone-500 font-medium block mt-0.5 leading-tight">ratings</span>
                  </div>

                  <div className="w-[1px] h-6 bg-stone-300/80 shrink-0" />

                  {/* Stat 2: Pujas Conducted */}
                  <div className="text-center flex-1 px-1">
                    <span className="block text-sm sm:text-base lg:text-lg font-extrabold text-[#1f1a17] leading-tight">24L+</span>
                    <span className="text-[10px] sm:text-xs text-stone-500 font-medium block mt-0.5 leading-tight">pujas conducted</span>
                  </div>

                  <div className="w-[1px] h-6 bg-stone-300/80 shrink-0" />

                  {/* Stat 3: Average Ratings */}
                  <div className="text-center flex-1 px-1">
                    <div className="flex items-center justify-center gap-0.5 sm:gap-1 leading-tight">
                      <span className="text-sm sm:text-base lg:text-lg font-extrabold text-[#1f1a17]">4.9/5</span>
                      <span className="text-amber-400 text-xs sm:text-sm">⭐</span>
                    </div>
                    <span className="text-[10px] sm:text-xs text-stone-500 font-medium block mt-0.5 leading-tight">Average ratings</span>
                  </div>
                </div>

                {/* Action Buttons: Wishlist & Share */}
                <div className="flex items-center justify-end gap-2 shrink-0">
                  <WishlistButton
                    itemId={puja._id}
                    text="Wishlist"
                    className="flex-initial border border-stone-300 hover:border-stone-500 bg-white text-stone-800 font-medium text-xs sm:text-sm px-3.5 sm:px-4 py-1.5 rounded-full flex items-center justify-center gap-1.5 transition-all active:scale-95 shadow-xs"
                    iconClassName="w-3.5 h-3.5 sm:w-4 sm:h-4"
                  />

                  <button
                    type="button"
                    aria-label="Share puja"
                    onClick={() => setShareModalOpen(true)}
                    className="flex-initial border border-stone-300 hover:border-stone-500 bg-white text-stone-800 font-medium text-xs sm:text-sm px-3.5 sm:px-4 py-1.5 rounded-full flex items-center justify-center gap-1.5 transition-all active:scale-95 shadow-xs"
                  >
                    <svg className="w-3.5 h-3.5 sm:w-4 sm:h-4 fill-none stroke-current" strokeWidth="2" viewBox="0 0 24 24">
